function fallbackDecision(errorMessage = 'AI Decision Engine unavailable or returned invalid output.') {
  return [
    {
      json: {
        severity: 'Medium',
        confidence: 0,
        decision: 'Escalate',
        reason: errorMessage,
        mitre: ['N/A'],
        recommended_actions: [
          'Review the normalized security context manually',
          'Validate threat intelligence and source IP reputation',
          'Decide whether containment is required'
        ],
        executive_summary: 'The security event could not be evaluated by the AI decision engine. The case was routed to manual analysis to avoid unsafe automated action.',
        response_policy_reason: 'Fail-safe behavior: when the AI decision engine fails or returns invalid output, the workflow defaults to manual analysis and does not execute automated containment.',
        ai_engine_status: 'failed',
        workflow_fallback: true
      }
    }
  ];
}

try {
  const raw =
    $json?.content?.parts?.[0]?.text ||
    $json?.text ||
    $json?.response ||
    '';

  if (!raw) {
    const errorMessage =
      $json?.error?.message ||
      $json?.message ||
      'Gemini returned no usable response. Possible quota, token, API, or model error.';

    return fallbackDecision(errorMessage);
  }

  const cleaned = raw
    .replace(/```json/g, '')
    .replace(/```/g, '')
    .trim();

  const parsed = JSON.parse(cleaned);

  const allowedDecisions = ['Ignore', 'Monitor', 'Escalate', 'Contain'];
  const allowedSeverity = ['Low', 'Medium', 'High', 'Critical'];

  if (!allowedDecisions.includes(parsed.decision)) {
    return fallbackDecision(`Invalid AI decision returned: ${parsed.decision}`);
  }

  if (!allowedSeverity.includes(parsed.severity)) {
    parsed.severity = 'Medium';
  }

  parsed.confidence = Number(parsed.confidence || 0);

  if (!Array.isArray(parsed.recommended_actions)) {
    parsed.recommended_actions = [
      'Review the event manually',
      'Validate threat intelligence',
      'Determine appropriate response'
    ];
  }

  if (!Array.isArray(parsed.mitre)) {
    parsed.mitre = ['N/A'];
  }

  parsed.ai_engine_status = 'success';
  parsed.workflow_fallback = false;

  return [
    {
      json: parsed
    }
  ];

} catch (error) {
  return fallbackDecision(`Failed to parse Gemini response: ${error.message}`);
}

