(() => {
  const location = String($json.body?.location || "").toLowerCase();
  const decoder = String($json.body?.decoder?.name || "").toLowerCase();
  const groups = $json.body?.rule?.groups || [];

  if ($json.body?.data?.eventid || location.includes("cowrie")) return "cowrie";
  if ($json.body?.data?.win?.system?.eventID || groups.includes("windows") || groups.includes("sysmon")) return "windows";
  if (groups.includes("linux") || decoder.includes("sshd") || decoder.includes("sudo")) return "linux";
  if ($json.body?.agent?.name) return "wazuh_agent";

  return "unknown";
})()
}}

