(() => {
  const winEventId = String($json.body?.data?.win?.system?.eventID || "");
  const cowrieEventId = String($json.body?.data?.eventid || "");
  const description = String($json.body?.rule?.description || "").toLowerCase();
  const fullLog = String($json.body?.full_log || "").toLowerCase();

  if (cowrieEventId === "cowrie.command.input") return "command_execution";
  if (cowrieEventId === "cowrie.session.file_download") return "file_download";
  if (cowrieEventId === "cowrie.session.file_upload") return "file_upload";
  if (cowrieEventId === "cowrie.login.success") return "authentication_success";
  if (cowrieEventId === "cowrie.login.failed") return "authentication_failure";

  if (winEventId === "1" || winEventId === "4688") return "process_creation";
  if (winEventId === "3") return "network_connection";
  if (winEventId === "11") return "file_creation";
  if (winEventId === "22") return "dns_query";
  if (winEventId === "4624") return "authentication_success";
  if (winEventId === "4625") return "authentication_failure";

  if (description.includes("command") || fullLog.includes("command=")) return "command_execution";
  if (description.includes("file") || fullLog.includes("sha256") || fullLog.includes("shasum")) return "file_activity";
  if (description.includes("login") || description.includes("authentication")) return "authentication_activity";

  return "unknown";
})()
}}
